from itertools import combinations

n = 14
target_edges = 19
min_girth = 7

# First, let's enumerate all cycles of length 3, 4, 5, 6
# and ensure at least one edge from each cycle is NOT in our graph

def find_all_cycles(n, max_len):
    """Find all cycles of length 3 to max_len."""
    cycles = []

    def dfs(start, current, path, visited):
        if len(path) > max_len:
            return
        for neighbor in range(current + 1, n):  # Only look forward to avoid duplicates
            if neighbor == start and len(path) >= 3:
                cycles.append(tuple(sorted(path)))
            elif neighbor not in visited and len(path) < max_len:
                visited.add(neighbor)
                dfs(start, neighbor, path + [neighbor], visited)
                visited.remove(neighbor)

    for start in range(n):
        dfs(start, start, [start], {start})

    # Remove duplicates
    unique_cycles = set()
    for c in cycles:
        unique_cycles.add(c)

    return list(unique_cycles)

